const fs = require('fs');
const path = require('path');
const PDFDocument = require('pdfkit');

const TEMPLATE_BASE64 = '';

function val(...a) {
  for (const x of a) if (x !== undefined && x !== null && String(x).trim()) return String(x);
  return '';
}
function fontFile() {
  const a = [
    '/system/fonts/NotoNaskhArabic-Regular.ttf',
    '/system/fonts/NotoSansArabic-Regular.ttf',
    '/usr/share/fonts/truetype/noto/NotoNaskhArabic-Regular.ttf',
    '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
  ];
  return a.find(fs.existsSync) || null;
}
function dateOnly(x) {
  if (!x) return '';
  const d = new Date(x);
  if (Number.isNaN(d.getTime())) return String(x);
  return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
}
function money(x) {
  const n = Number(x);
  return Number.isFinite(n) ? n.toLocaleString('en-US',{maximumFractionDigits:2}) : val(x,'0');
}
function rtl(x) {
  const s = val(x);
  if (!s) return '';
  if (/^[0-9A-Za-z ._/:()+-]+$/.test(s)) return s;
  return s.split('\n').map(v => v.split('').reverse().join('')).join('\n');
}
function put(doc,x,y,w,v,size=9,align='right') {
  doc.fontSize(size).fillColor('#173b8f');
  doc.text(rtl(v),x,y,{width:w,align,lineBreak:false});
}

function createWorkOrderPdf(workOrder, services=[], materials=[]) {
  const dir = path.join(process.cwd(),'uploads','work-orders');
  fs.mkdirSync(dir,{recursive:true});

  const no = val(workOrder.work_order_no,workOrder.work_order_number,workOrder.number,'work-order');
  const fileName = `${no}.pdf`;
  const filePath = path.join(dir,fileName);

  const doc = new PDFDocument({size:'A4',margin:0});
  const stream = fs.createWriteStream(filePath);
  doc.pipe(stream);

  // صورة التصميم المرفقة كخلفية.
  doc.image(Buffer.from(TEMPLATE_BASE64,'base64'),0,0,{width:595.28,height:841.89});

  const f = fontFile();
  if (f) doc.font(f);

  // التاريخ + رقم الأمر + موعد التسليم
  put(doc, dateOnly(val(workOrder.received_at,workOrder.created_at,workOrder.date)),
      405,155,120,9.5,'center');
  put(doc, no, 70,151,145,14,'center');
  put(doc, dateOnly(val(workOrder.delivery_date,workOrder.due_date,
      workOrder.promised_date,workOrder.promised_at,workOrder.estimated_delivery_date)),
      215,184,160,9.5,'center');

  // العميل
  put(doc,val(workOrder.customer_name,workOrder.customer_full_name),
      65,220,425,9.5,'right');
  put(doc,val(workOrder.customer_phone,workOrder.phone,workOrder.mobile),
      65,249,425,9.5,'right');

  // تفاصيل الطلب / العدد / الألوان
  const items = Array.isArray(services) && services.length ? services :
                (Array.isArray(materials) ? materials : []);
  const detailX=238, detailW=325, qtyX=165, qtyW=69, colorX=28, colorW=130;
  items.slice(0,10).forEach((item,i)=>{
    const y=318+i*29;
    put(doc,val(item.service_name,item.name,item.service,item.description,item.material_name),
        detailX,y,detailW,8.5,'right');
    put(doc,val(item.quantity,item.qty,'1'),qtyX,y,qtyW,8.5,'center');
    put(doc,val(item.colors,item.color,item.colour,item.color_name,item.leather_color),
        colorX,y,colorW,8,'center');
  });

  // القيمة / المدفوع / الباقي
  const subtotal=val(workOrder.subtotal,workOrder.sub_total,workOrder.total_amount,'0');
  const paid=val(workOrder.deposit_amount,workOrder.deposit,workOrder.paid_amount,workOrder.paid,'0');
  let balance=val(workOrder.balance_amount,workOrder.remaining_amount,workOrder.balance);
  if (balance==='') balance=String((Number(subtotal)||0)-(Number(paid)||0));

  put(doc,money(subtotal),75,653,410,9.5,'right');
  put(doc,money(paid),75,681,410,9.5,'right');
  put(doc,money(balance),75,709,410,9.5,'right');

  // الموظف المختص واسم العميل
  put(doc,val(workOrder.employee_name,workOrder.employee_full_name,
      workOrder.assigned_employee_name,workOrder.technician_name,
      workOrder.employee,workOrder.assigned_to_name),
      360,765,170,9,'center');
  put(doc,val(workOrder.customer_name,workOrder.customer_full_name),
      65,765,170,9,'center');

  doc.end();

  return new Promise((resolve,reject)=>{
    stream.on('finish',()=>resolve({fileName,filePath}));
    stream.on('error',reject);
  });
}

module.exports={createWorkOrderPdf};
